function challengeFor(d){const base=challenges[(d-1)%challenges.length];const palette=dailyColors[(d-1)%dailyColors.length];return {...base,color:palette.hex,name:palette.name}}
function loadDay(d){selectedDay=d;let c=challengeFor(d);let fact=environmentalFacts[(d-1)%environmentalFacts.length];colorBox.style.background=c.color;colorName.textContent=`${c.name} · ${c.color.toUpperCase()}`;color.value=c.color;dayLabel.textContent=`Día ${d} de 365`;challengeTitle.textContent=c.title;challengeText.textContent=c.text;reflection.textContent=c.reflection;challengeODS.textContent=c.ods;dailyFactText.textContent=fact.text;dailyFactSource.textContent=fact.source;dailyFactSource.href=fact.url;updateStats()}
function completeToday(){if(!completed.includes(selectedDay))completed.push(selectedDay);localStorage.setItem("pec_completed",JSON.stringify(completed));updateStats();buildCalendar()}
function updateStats(){completedCount.textContent=completed.length;progressPct.textContent=Math.round(completed.length/365*100)+"%"}
function buildCalendar(){calendar.innerHTML="";for(let i=1;i<=365;i++){let b=document.createElement("button");b.className="day"+(completed.includes(i)?" done":"")+(i===selectedDay?" today":"");b.textContent=i;b.onclick=()=>{loadDay(i);showPage("reto");buildCalendar()};calendar.appendChild(b)}}
function setPreview(t){document.body.classList.toggle("preview-mobile",t==="mobile");pcBtn.classList.toggle("active",t==="pc");mobileBtn.classList.toggle("active",t==="mobile")}
const canvas=document.getElementById("canvas"),ctx=canvas.getContext("2d");let drawing=false,startX=0,startY=0,lastX=0,lastY=0,undoStack=[],redoStack=[];
function snapshot(){return canvas.toDataURL("image/png")}function restore(data){let im=new Image();im.onload=()=>{ctx.clearRect(0,0,canvas.width,canvas.height);ctx.drawImage(im,0,0)};im.src=data}
function pushUndo(){undoStack.push(snapshot());if(undoStack.length>30)undoStack.shift();redoStack=[]}
function pos(e){let r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)*canvas.width/r.width,y:(e.clientY-r.top)*canvas.height/r.height}}
function style(){let t=tool.value,s=+size.value;ctx.lineCap="round";ctx.lineJoin="round";ctx.lineWidth=s;ctx.globalAlpha=+opacity.value/100;ctx.strokeStyle=color.value;ctx.fillStyle=color.value;if(t==="eraser"){ctx.globalCompositeOperation="destination-out";ctx.globalAlpha=1}else ctx.globalCompositeOperation="source-over";if(t==="pencil"){ctx.lineWidth=Math.max(1,s*.45);ctx.globalAlpha=.9}if(t==="crayon"){ctx.lineWidth=s*1.4;ctx.globalAlpha=.7}if(t==="marker"){ctx.lineWidth=s*1.8;ctx.globalAlpha=.45}if(t==="watercolor"){ctx.lineWidth=s*2;ctx.globalAlpha=.16}if(t==="airbrush"){ctx.lineWidth=s*3;ctx.globalAlpha=.08}}
function startDraw(e){e.preventDefault();pushUndo();drawing=true;let p=pos(e);startX=lastX=p.x;startY=lastY=p.y;let t=tool.value;if(["brush","pencil","crayon","marker","watercolor","airbrush","eraser"].includes(t)){style();ctx.beginPath();ctx.moveTo(lastX,lastY);ctx.lineTo(lastX+.1,lastY+.1);ctx.stroke()}}
function draw(e){if(!drawing)return;e.preventDefault();let p=pos(e),t=tool.value;if(["brush","pencil","crayon","marker","watercolor","airbrush","eraser"].includes(t)){style();ctx.beginPath();ctx.moveTo(lastX,lastY);ctx.lineTo(p.x,p.y);ctx.stroke();lastX=p.x;lastY=p.y}}
function endDraw(e){if(!drawing)return;drawing=false;let t=tool.value,p=pos(e||{clientX:0,clientY:0});if(["line","rect","circle","triangle","star"].includes(t)){style();drawShape(t,startX,startY,p.x,p.y)}ctx.globalAlpha=1;ctx.globalCompositeOperation="source-over"}
function drawShape(t,x1,y1,x2,y2){let f=fill.checked;ctx.beginPath();if(t==="line"){ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.stroke();return}if(t==="rect")ctx.rect(x1,y1,x2-x1,y2-y1);if(t==="circle"){let r=Math.hypot(x2-x1,y2-y1);ctx.arc(x1,y1,r,0,Math.PI*2)}if(t==="triangle"){ctx.moveTo((x1+x2)/2,y1);ctx.lineTo(x2,y2);ctx.lineTo(x1,y2);ctx.closePath()}if(t==="star"){let cx=(x1+x2)/2,cy=(y1+y2)/2,r=Math.max(Math.abs(x2-x1),Math.abs(y2-y1))/2;for(let i=0;i<10;i++){let a=-Math.PI/2+i*Math.PI/5,rr=i%2?r*.42:r,x=cx+Math.cos(a)*rr,y=cy+Math.sin(a)*rr;if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y)}ctx.closePath()}f?ctx.fill():ctx.stroke()}
function undo(){if(!undoStack.length)return;redoStack.push(snapshot());restore(undoStack.pop())}function redo(){if(!redoStack.length)return;undoStack.push(snapshot());restore(redoStack.pop())}
function clearCanvas(){pushUndo();ctx.clearRect(0,0,canvas.width,canvas.height);ctx.fillStyle="#fff";ctx.fillRect(0,0,canvas.width,canvas.height)}
function savePNG(){let a=document.createElement("a");a.download="planeta-en-365-colores.png";a.href=canvas.toDataURL("image/png");a.click()}
canvas.addEventListener("pointerdown",startDraw);canvas.addEventListener("pointermove",draw);canvas.addEventListener("pointerup",endDraw);canvas.addEventListener("pointercancel",endDraw);canvas.addEventListener("pointerleave",endDraw);
ctx.fillStyle="#fff";ctx.fillRect(0,0,canvas.width,canvas.height);loadDay(1);buildCalendar();

